def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    def fill_line(vals, coords):
        n = len(vals)
        i = 0
        while i < n:
            if vals[i] != bg:
                i += 1
                continue
            a = i
            while i < n and vals[i] == bg:
                i += 1
            b = i
            # A gap must be bracketed by the same color, with a stroke
            # of at least two cells continuing on one of its sides.
            if a > 0 and b < n and vals[a - 1] == vals[b]:
                color = vals[a - 1]
                left = a - 1
                while left > 0 and vals[left - 1] == color:
                    left -= 1
                right = b
                while right + 1 < n and vals[right + 1] == color:
                    right += 1
                if (a - left >= 2) or (right - b + 1 >= 2):
                    for k in range(a, b):
                        r, c = coords(k)
                        out[r][c] = 2

    for r in range(h):
        fill_line(grid[r], lambda c, r=r: (r, c))
    for c in range(w):
        fill_line([grid[r][c] for r in range(h)], lambda r, c=c: (r, c))

    return out
